#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    vector<unsigned> prev(n), cur(n);
    for (auto &x : prev) scanf("%u", &x);
    // best[l*n+r] = max f over all subarrays of [l, r]
    vector<unsigned> best((size_t)n * n, 0);
    for (int i = 0; i < n; i++) best[(size_t)i * n + i] = prev[i];
    for (int size = 2; size <= n; size++) {
        for (int l = 0; l + size - 1 < n; l++) {
            int r = l + size - 1;
            unsigned v = prev[l] ^ prev[l + 1];  // f(l,r) = f(l,r-1) ^ f(l+1,r)
            cur[l] = v;
            best[(size_t)l * n + r] = max({v, best[(size_t)l * n + r - 1], best[(size_t)(l + 1) * n + r]});
        }
        swap(prev, cur);
    }
    string out;
    char buf[16];
    for (int i = 0; i < q; i++) {
        int l, r;
        scanf("%d %d", &l, &r);
        int len = snprintf(buf, sizeof buf, "%u\n", best[(size_t)l * n + r]);
        out.append(buf, len);
    }
    fputs(out.c_str(), stdout);
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return null;
        ByteArrayOutputStream sb = new ByteArrayOutputStream();
        while (c != -1 && c > ' ') { sb.write(c); c = read(); }
        return sb.toString(java.nio.charset.StandardCharsets.UTF_8);
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        int[] prev = new int[n], cur = new int[n];
        for (int i = 0; i < n; i++) prev[i] = nextInt();
        // best[l*n+r] = max f over all subarrays of [l, r]
        int[] best = new int[n * n];
        for (int i = 0; i < n; i++) best[i * n + i] = prev[i];
        for (int size = 2; size <= n; size++) {
            for (int l = 0; l + size - 1 < n; l++) {
                int r = l + size - 1;
                int v = prev[l] ^ prev[l + 1];  // f(l,r) = f(l,r-1) ^ f(l+1,r)
                cur[l] = v;
                best[l * n + r] = Math.max(v, Math.max(best[l * n + r - 1], best[(l + 1) * n + r]));
            }
            int[] t = prev; prev = cur; cur = t;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int l = nextInt(), r = nextInt();
            sb.append(best[l * n + r]).append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	n, q := readInt(), readInt()
	prev := make([]uint32, n)
	cur := make([]uint32, n)
	for i := range prev {
		prev[i] = uint32(readInt())
	}
	// best[l*n+r] = max f over all subarrays of [l, r]
	best := make([]uint32, n*n)
	for i := 0; i < n; i++ {
		best[i*n+i] = prev[i]
	}
	for size := 2; size <= n; size++ {
		for l := 0; l+size-1 < n; l++ {
			r := l + size - 1
			v := prev[l] ^ prev[l+1] // f(l,r) = f(l,r-1) ^ f(l+1,r)
			cur[l] = v
			best[l*n+r] = max(v, best[l*n+r-1], best[(l+1)*n+r])
		}
		prev, cur = cur, prev
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	buf := make([]byte, 0, 16)
	for i := 0; i < q; i++ {
		l, r := readInt(), readInt()
		buf = strconv.AppendUint(buf[:0], uint64(best[l*n+r]), 10)
		buf = append(buf, '\n')
		w.Write(buf)
	}
}
